<script>(()=>{const tree=document.querySelector('.team-tree'),panel=document.getElementById('member-detail'),nameEl=document.getElementById('detail-name'),metaEl=document.getElementById('detail-meta'),childrenEl=document.getElementById('detail-children'),reset=document.getElementById('focus-reset');if(!tree)return;const cards=[...tree.querySelectorAll('.member-card')];const clear=()=>{tree.classList.remove('focus-mode');cards.forEach(card=>{card.style.display='';card.classList.remove('focus-selected','focus-child')});panel.hidden=true};cards.forEach(card=>card.addEventListener('click',()=>{const li=card.closest('li'),allowed=new Set([li,...li.querySelectorAll('li')]);cards.forEach(other=>{const owner=other.closest('li');other.style.display=allowed.has(owner)?'':'none';other.classList.toggle('focus-selected',other===card);other.classList.toggle('focus-child',other!==card&&allowed.has(owner))});tree.classList.add('focus-mode');nameEl.textContent=card.dataset.memberName;metaEl.textContent=card.dataset.memberMeta;childrenEl.textContent=`${card.dataset.memberChildren} direct referrals`;panel.hidden=false;panel.scrollIntoView({behavior:'smooth',block:'nearest'})}));reset?.addEventListener('click',clear);document.getElementById('detail-close')?.addEventListener('click',clear)})();</script>
